# shellcheck shell=bash
# SPDX-License-Identifier: GPL-2.0-or-later

# What the installer trusts: the pinned ReShade setup checksums (lib/reshade_pins.sh) and the
# pinned shader pack commits (lib/shader_pins.sh). Both files are generated by the scripts in
# scripts/release/; this module only reads them and applies the policy.

# Print the pinned SHA-256 of ReShade_Setup_<name>.exe (name is a version, with _Addon for the
# add-on build). Fails when that build is not pinned.
function reshadeSetupPinnedHash() {
    local _name="$1" _pinName _pinHash

    declare -F listPinnedReshadeSetups >/dev/null || return 1
    while read -r _pinName _pinHash; do
        [[ $_pinName == "$_name" ]] || continue
        printf '%s\n' "$_pinHash"
        return 0
    done < <(listPinnedReshadeSetups)
    return 1
}

# Print the newest pinned version: the add-on build when $1 is 1, the standard build otherwise.
function newestPinnedReshadeVersion() {
    local _addon="${1:-0}" _pinName _pinHash

    declare -F listPinnedReshadeSetups >/dev/null || return 1
    while read -r _pinName _pinHash; do
        if [[ $_addon -eq 1 ]]; then
            [[ $_pinName == *_Addon ]] || continue
        else
            [[ $_pinName != *_Addon ]] || continue
        fi
        printf '%s\n' "$_pinName"
        return 0
    done < <(listPinnedReshadeSetups | sort -t ' ' -k1,1Vr)
    return 1
}

# True when a ReShade build may be downloaded: the user pinned a digest, the build is pinned here,
# or unpinned downloads were allowed explicitly.
function reshadeSetupIsAcceptable() {
    [[ -n ${RESHADE_SETUP_SHA256:-} || ${RESHADE_ALLOW_UNPINNED:-0} == 1 ]] && return 0
    reshadeSetupPinnedHash "$1" >/dev/null
}

# Check a downloaded setup executable. RESHADE_SETUP_SHA256 wins when set; otherwise the built-in
# pin for that build must match, and a build with no pin is refused unless RESHADE_ALLOW_UNPINNED=1.
function verifyReshadeDownloadHash() {
    local _file="$1" _name="$2"
    local _expectedHash="${RESHADE_SETUP_SHA256:-}" _source="RESHADE_SETUP_SHA256"
    local _actualHash _rest

    if [[ -n $_expectedHash ]]; then
        [[ $_expectedHash =~ ^[0-9a-fA-F]{64}$ ]] || {
            failWith "$EXIT_USAGE" "RESHADE_SETUP_SHA256 must be a 64-character hexadecimal SHA-256 digest."
            return 1
        }
    elif _expectedHash=$(reshadeSetupPinnedHash "$_name"); then
        _source="the checksum built into this installer"
    elif [[ ${RESHADE_ALLOW_UNPINNED:-0} == 1 ]]; then
        printWarn "Warning: ReShade $_name has no built-in checksum. Installing it unverified because RESHADE_ALLOW_UNPINNED=1."
        return 0
    else
        failWith "$EXIT_INTEGRITY" "ReShade $_name has no built-in checksum, so it was not installed. Update reshadelinux, set RESHADE_SETUP_SHA256 to the digest you expect, or set RESHADE_ALLOW_UNPINNED=1 to install it unverified."
        return 1
    fi

    read -r _actualHash _rest < <(sha256sum "$_file")
    [[ ${_actualHash,,} == "${_expectedHash,,}" ]] || {
        failWith "$EXIT_INTEGRITY" "ReShade download integrity check failed against $_source. Expected $_expectedHash but calculated $_actualHash."
        return 1
    }
}

# Print the pinned commit of a shader pack, keyed by its URL and branch (empty for the default
# branch). Fails when the pack is not pinned, as with packs added through SHADER_REPOS.
function shaderRepoPinnedCommit() {
    local _uri="$1" _branch="${2:--}" _pinUri _pinBranch _pinCommit

    declare -F listPinnedShaderRepos >/dev/null || return 1
    while read -r _pinUri _pinBranch _pinCommit; do
        [[ $_pinUri == "$_uri" && $_pinBranch == "$_branch" ]] || continue
        [[ $_pinCommit =~ ^[0-9a-f]{40}$ ]] || return 1
        printf '%s\n' "$_pinCommit"
        return 0
    done < <(listPinnedShaderRepos)
    return 1
}

# The commit a pack should be checked out at, or nothing to follow its branch. SHADER_REPOS_TRACK_HEAD=1
# turns pinning off for every pack.
function shaderRepoWantedCommit() {
    [[ ${SHADER_REPOS_TRACK_HEAD:-0} == 1 ]] && return 1
    shaderRepoPinnedCommit "$1" "$2"
}
